// Node: Set Session
// Position: Right after Schedule Trigger
// Output: 1 item with session metadata used by all downstream nodes

const now = new Date();
const utcHour = now.getUTCHours();
const utcMinute = now.getUTCMinutes();
const totalUTCMinutes = utcHour * 60 + utcMinute;

// EDT = UTC-4 (summer). Adjust to UTC-5 in winter.
// Morning:  8:30 AM ET = 12:30 UTC → range 720–840 min
// Midday:  12:00 PM ET = 16:00 UTC → range 840–1230 min
// Close:    4:30 PM ET = 20:30 UTC → range 1230+ min
let session_type;
if (totalUTCMinutes >= 720 && totalUTCMinutes < 840) {
  session_type = 'morning';
} else if (totalUTCMinutes >= 840 && totalUTCMinutes < 1230) {
  session_type = 'midday';
} else {
  session_type = 'close';
}

const dateStr = now.toISOString().split('T')[0];  // YYYY-MM-DD
const session_id = `${dateStr}_${session_type}`;

return [{
  json: {
    session_type,          // 'morning' | 'midday' | 'close'
    session_id,            // e.g. '2026-05-19_morning'
    session_date: dateStr,
    utc_timestamp: now.toISOString(),
    is_morning: session_type === 'morning',
  }
}];

const r=$input.first()?.json||{};
const all=Array.isArray(r.body)?r.body:[];
return [{json:{_items:all,_count:all.length}}];

const r=$input.first()?.json||{};
const all=Array.isArray(r.body)?r.body:[];
return [{json:{_items:all,_count:all.length}}];

// Node: Compute Derived Metrics
// Position: After Merge (node 17) — all data is now available
// Reads from named nodes via $("NodeName").all()
// Output: 1 item containing ALL context needed by specialists and orchestrator

// ── COLLECT RAW DATA ──────────────────────────────────────────────────────────

const session     = $("Set Session").first().json;
const accountRaw  = $("Fetch Alpaca Account").first().json;
const positions   = $("Fetch Alpaca Positions").all().map(i => i.json);
const openOrders  = $("Fetch Alpaca Open Orders").all().map(i => i.json);
const priceResp   = $("Fetch Price Bars").first().json;

const signalRows      = $("Load Signal History").all().map(i => i.json);
const accuracyRows    = $("Load Specialist Accuracy").all().map(i => i.json);
const patternRows     = $("Load Pattern Performance").all().map(i => i.json);
const lessonRows      = $("Load Trade Lessons").all().map(i => i.json);
const watchlistRows   = $("Load Watchlist").all().map(i => i.json);
const earningsRows    = $("Load Earnings Calendar").all().map(i => i.json);
const correlRows      = $("Load Correlation Matrix").all().map(i => i.json);
const snapshotRows    = $("Load Portfolio Snapshots").all().map(i => i.json);

// Fundamentals: morning = just stored, not-morning = from cache
let fundamentalsRows = [];
try {
  fundamentalsRows = $("Load Fundamentals Cache").all().map(i => i.json);
} catch (_) {
  // morning path — fundamentals were stored in a sub-loop, reference by node name if applicable
  // fallback: empty (specialists will note missing data)
}

// ── PRICE MAP ─────────────────────────────────────────────────────────────────
// Alpaca bars response: { bars: { TICKER: [{t, o, h, l, c, v}, ...] } }
const allBars = (priceResp && priceResp.bars) ? priceResp.bars : {};
const priceMap = {};

for (const [ticker, bars] of Object.entries(allBars)) {
  if (!Array.isArray(bars) || bars.length === 0) continue;
  const sorted = [...bars].sort((a, b) => new Date(a.t) - new Date(b.t));
  const current    = sorted[sorted.length - 1].c;
  const prev1d     = sorted.length >= 2  ? sorted[sorted.length - 2].c  : current;
  const prev5d     = sorted.length >= 6  ? sorted[sorted.length - 6].c  : current;
  const prev30d    = sorted.length >= 31 ? sorted[sorted.length - 31].c : current;

  // ATR-14: average of last 14 True Ranges
  let atr14 = 0;
  if (sorted.length >= 15) {
    let sumTR = 0;
    for (let i = sorted.length - 14; i < sorted.length; i++) {
      const h = sorted[i].h, l = sorted[i].l, pc = sorted[i - 1].c;
      sumTR += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
    }
    atr14 = sumTR / 14;
  }

  // Trailing stop %: ATR×2.5 as % of current price, clamped 5–15%
  const trailPct = atr14 > 0
    ? Math.min(Math.max((atr14 * 2.5 / current) * 100, 5), 15)
    : 8;  // default 8% if ATR unavailable

  priceMap[ticker] = {
    current:        parseFloat(current.toFixed(2)),
    chg_1d_pct:     parseFloat(((current - prev1d)  / prev1d  * 100).toFixed(2)),
    chg_5d_pct:     parseFloat(((current - prev5d)  / prev5d  * 100).toFixed(2)),
    chg_30d_pct:    parseFloat(((current - prev30d) / prev30d * 100).toFixed(2)),
    atr14:          parseFloat(atr14.toFixed(4)),
    trail_pct:      parseFloat(trailPct.toFixed(2)),
    week_52_high:   parseFloat(Math.max(...sorted.map(b => b.h)).toFixed(2)),
    week_52_low:    parseFloat(Math.min(...sorted.map(b => b.l)).toFixed(2)),
  };
}

// ── FUNDAMENTALS MAP ─────────────────────────────────────────────────────────
const fundamentalsMap = {};
for (const row of fundamentalsRows) {
  if (row && row.ticker) fundamentalsMap[row.ticker] = row;
}

// ── EARNINGS AT-RISK ──────────────────────────────────────────────────────────
// Open positions whose underlying stock has earnings within 7 days
const today = new Date();
today.setHours(0, 0, 0, 0);

const earningsAtRisk = [];
for (const pos of positions) {
  const ticker = pos.symbol;
  const entry = earningsRows.find(e => e.ticker === ticker);
  if (!entry || !entry.earnings_date) continue;
  const earnDate = new Date(entry.earnings_date);
  const daysUntil = Math.round((earnDate - today) / 86400000);
  if (daysUntil >= 0 && daysUntil <= 7) {
    earningsAtRisk.push({
      ticker,
      earnings_date: entry.earnings_date,
      days_until: daysUntil,
      risk_level: daysUntil <= 2 ? 'HIGH' : 'MEDIUM',
    });
  }
}

// ── TRAILING STOP PROXIMITY ───────────────────────────────────────────────────
const stopProximity = [];
for (const pos of positions) {
  const ticker = pos.symbol;
  const currentPrice = parseFloat(pos.current_price);
  // Find the GTC trailing stop order for this position
  const stopOrder = openOrders.find(o =>
    o.symbol === ticker &&
    o.type === 'trailing_stop' &&
    ['accepted', 'pending_new', 'new'].includes(o.status)
  );
  if (stopOrder && stopOrder.stop_price) {
    const stopPrice  = parseFloat(stopOrder.stop_price);
    const distPct    = Math.abs((currentPrice - stopPrice) / currentPrice * 100);
    stopProximity.push({
      ticker,
      current_price: currentPrice,
      stop_price:    parseFloat(stopPrice.toFixed(2)),
      distance_pct:  parseFloat(distPct.toFixed(2)),
      risk:          distPct < 3 ? 'CRITICAL' : distPct < 6 ? 'WARNING' : 'OK',
    });
  }
}

// ── CORRELATION FLAGS ─────────────────────────────────────────────────────────
// Build map: ticker → [{ open_position, correlation }] for any correlation > 0.70
const corrMap = {};
for (const row of correlRows) {
  if (Math.abs(row.correlation) > 0.70) {
    if (!corrMap[row.ticker_a]) corrMap[row.ticker_a] = [];
    if (!corrMap[row.ticker_b]) corrMap[row.ticker_b] = [];
    corrMap[row.ticker_a].push({ open_position: row.ticker_b, correlation: row.correlation });
    corrMap[row.ticker_b].push({ open_position: row.ticker_a, correlation: row.correlation });
  }
}

const openTickers = new Set(positions.map(p => p.symbol));
// correlationFlags[candidateTicker] = [{open_position, correlation}]
const correlationFlags = {};
for (const [ticker, corrs] of Object.entries(corrMap)) {
  const overlaps = corrs.filter(c => openTickers.has(c.open_position));
  if (overlaps.length > 0) correlationFlags[ticker] = overlaps;
}

// ── SIGNAL HISTORY BY NICHE ───────────────────────────────────────────────────
const NICHES = [
  'cybersecurity', 'defense', 'nuclear_uranium', 'copper_minerals',
  'ai_semiconductors', 'cloud_hyperscalers', 'oil_gas', 'data_centers'
];

const signalsByNiche = {};
for (const niche of NICHES) {
  const nicheRows = signalRows
    .filter(r => r.niche === niche)
    .sort((a, b) => new Date(a.created_at) - new Date(b.created_at))  // oldest first
    .slice(-5);  // last 5

  if (nicheRows.length === 0) {
    signalsByNiche[niche] = { signals: [], pattern: 'FIRST_SIGNAL', formatted: 'No history' };
    continue;
  }

  const dirs = nicheRows.map(r => r.direction);
  const bullCount = dirs.filter(d => d === 'BULLISH').length;
  const bearCount = dirs.filter(d => d === 'BEARISH').length;

  let pattern = 'NOISE';

  // REVERSAL: last 3 all same direction, opposite to direction of prior sessions
  if (dirs.length >= 4) {
    const last3  = dirs.slice(-3);
    const prior  = dirs.slice(0, -3);
    const l3Bull = last3.every(d => d === 'BULLISH');
    const l3Bear = last3.every(d => d === 'BEARISH');
    const priorMajBull = prior.filter(d => d === 'BULLISH').length >= Math.ceil(prior.length * 0.6);
    const priorMajBear = prior.filter(d => d === 'BEARISH').length >= Math.ceil(prior.length * 0.6);
    if ((l3Bull && priorMajBear) || (l3Bear && priorMajBull)) pattern = 'REVERSAL';
  }

  if (pattern !== 'REVERSAL') {
    if (bullCount >= 4 || bearCount >= 4)   pattern = 'TREND';
    else if (bullCount >= 3 || bearCount >= 3) pattern = 'BIAS';
    else                                        pattern = 'NOISE';
  }

  const formatted = nicheRows.map(r => {
    const c = r.conviction === 'HIGH' ? 'H' : r.conviction === 'MEDIUM' ? 'M' : 'L';
    return `${r.direction}(${r.confidence}/${c})`;
  }).join(' → ');

  signalsByNiche[niche] = { signals: nicheRows, pattern, formatted };
}

// ── SECTOR ROTATION SUMMARY ───────────────────────────────────────────────────
const rotationSummary = NICHES.map(niche => {
  const h = signalsByNiche[niche];
  if (!h.signals.length) return { niche, momentum: 'UNKNOWN', pattern: 'FIRST_SIGNAL' };
  const dirs = h.signals.map(s => s.direction);
  const recent = dirs.slice(-2);
  const prior  = dirs.slice(0, -2);
  const recentBullRate = recent.filter(d => d === 'BULLISH').length / recent.length;
  const priorBullRate  = prior.length > 0 ? prior.filter(d => d === 'BULLISH').length / prior.length : 0.5;
  const delta = recentBullRate - priorBullRate;
  const momentum = delta > 0.2 ? 'GAINING' : delta < -0.2 ? 'LOSING' : 'STABLE';
  return { niche, momentum, pattern: h.pattern, current_direction: dirs[dirs.length - 1] };
});

// ── PORTFOLIO P&L VS SPY ──────────────────────────────────────────────────────
const spyBars = allBars['SPY'] || [];
const spyCurrent = spyBars.length > 0 ? spyBars[spyBars.length - 1].c : null;

// Use first snapshot as baseline (start of experiment)
const sortedSnaps = [...snapshotRows].sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
const firstSnap = sortedSnaps[0];
const portfolioValue = parseFloat(accountRaw.portfolio_value);
const portfolioCumulativePct = firstSnap
  ? parseFloat(((portfolioValue - firstSnap.portfolio_value_usd) / firstSnap.portfolio_value_usd * 100).toFixed(2))
  : 0;
const spyStartPrice = firstSnap ? firstSnap.spy_price : spyCurrent;
const spyCumulativePct = (spyStartPrice && spyCurrent)
  ? parseFloat(((spyCurrent - spyStartPrice) / spyStartPrice * 100).toFixed(2))
  : 0;

const last7Snapshots = [...snapshotRows]
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
  .slice(0, 7)
  .reverse()
  .map(s => ({
    session: s.session,
    portfolio_value: s.portfolio_value_usd,
    spy_price: s.spy_price,
  }));

// ── SPECIALIST EFFECTIVE CONFIDENCE ──────────────────────────────────────────
const specialistEffectiveConf = {};
for (const row of accuracyRows) {
  const scaling = (row.hit_rate && row.avg_reported_confidence && row.avg_reported_confidence > 0)
    ? row.hit_rate / row.avg_reported_confidence
    : 1.0;
  specialistEffectiveConf[row.niche] = {
    scaling_factor:          parseFloat(scaling.toFixed(3)),
    hit_rate:                row.hit_rate,
    avg_reported_confidence: row.avg_reported_confidence,
    total_signals:           row.total_signals || 0,
    best_pattern:            row.best_pattern || null,
    worst_pattern:           row.worst_pattern || null,
  };
}

// ── PATTERN PERFORMANCE MAP ───────────────────────────────────────────────────
const patternPerfMap = {};
for (const row of patternRows) {
  const key = row.niche === 'ALL' ? row.pattern_type : `${row.pattern_type}_${row.niche}`;
  patternPerfMap[key] = {
    win_rate:       row.win_rate,
    avg_win_pct:    row.avg_win_pct,
    avg_loss_pct:   row.avg_loss_pct,
    expected_value: row.expected_value,
    total_trades:   row.total_trades,
  };
}

// ── OUTPUT ────────────────────────────────────────────────────────────────────
return [{
  json: {
    // Session
    session_type:      session.session_type,
    session_id:        session.session_id,
    session_date:      session.session_date,
    utc_timestamp:     session.utc_timestamp,

    // Portfolio state
    account: {
      portfolio_value:    parseFloat(accountRaw.portfolio_value),
      cash:               parseFloat(accountRaw.cash),
      buying_power:       parseFloat(accountRaw.buying_power),
      long_market_value:  parseFloat(accountRaw.long_market_value),
      short_market_value: parseFloat(accountRaw.short_market_value),
      equity:             parseFloat(accountRaw.equity),
    },
    positions,
    openOrders,

    // Price & fundamentals
    priceMap,
    fundamentalsMap,

    // Risk flags
    earningsAtRisk,
    stopProximity,
    correlationFlags,

    // Signals & rotation
    signalsByNiche,
    rotationSummary,

    // P&L
    portfolioValue,
    portfolioCumulativePct,
    spyCumulativePct,
    spyCurrent,
    last7Snapshots,

    // Feedback system
    specialistEffectiveConf,
    patternPerfMap,
    recentTradeLessons: lessonRows.slice(0, 5),
    watchlist: watchlistRows,
    earningsRows,
  }
}];

// Node: Build Orchestrator Input
// Position: After Parse & Save All Signals (receives 8 specialist items)
// Assembles the full orchestrator prompt from all available context
// Output: 1 item with system_prompt + user_prompt for OpenAI GPT-5.1

const ctx         = $("Compute Derived Metrics").first().json;
const specialists = $("Parse & Save All Signals").all().map(i => i.json);

// ── HELPER: Format positions ──────────────────────────────────────────────────
function formatPositions(positions, stopProximity, earningsAtRisk, priceMap) {
  if (!positions || positions.length === 0) return 'No open positions.';
  return positions.map(pos => {
    const ticker      = pos.symbol;
    const qty         = parseFloat(pos.qty);
    const side        = qty > 0 ? 'LONG' : 'SHORT';
    const entryPrice  = parseFloat(pos.avg_entry_price);
    const currentPrice= parseFloat(pos.current_price);
    const unrealPnl   = parseFloat(pos.unrealized_pl);
    const unrealPct   = parseFloat(pos.unrealized_plpc) * 100;
    const mktValue    = parseFloat(pos.market_value);
    const daysHeld    = pos.days_held || '?';  // custom field if tracked, else omit

    const stop        = stopProximity.find(s => s.ticker === ticker);
    const stopStr     = stop
      ? `| Stop: $${stop.stop_price} (${stop.distance_pct}% away — ${stop.risk})`
      : '| Stop: N/A';

    const earn = earningsAtRisk.find(e => e.ticker === ticker);
    const earnStr = earn
      ? `| ⚠️ EARNINGS IN ${earn.days_until}d (${earn.risk_level})`
      : '';

    return `  ${ticker} (${side}) — Entry: $${entryPrice} | Current: $${currentPrice} | Qty: ${Math.abs(qty)} | MktVal: $${Math.abs(mktValue).toFixed(0)} | P&L: ${unrealPct.toFixed(2)}% ($${unrealPnl.toFixed(0)}) ${stopStr} ${earnStr}`;
  }).join('\n');
}

// ── HELPER: Format signal history ─────────────────────────────────────────────
function formatSignalHistory(signalsByNiche) {
  return Object.entries(signalsByNiche).map(([niche, data]) => {
    const label = niche.padEnd(20);
    return `  ${label}: ${data.formatted || 'No history'} [Pattern: ${data.pattern}]`;
  }).join('\n');
}

// ── HELPER: Format specialist signals ────────────────────────────────────────
function formatSpecialistSignals(specialists) {
  return specialists.map(s => {
    const longPicks  = (s.long_picks  || []).map(p => `    LONG  ${p.ticker}: ${p.thesis} | Risk: ${p.key_risk} | Earnings: ${p.earnings_risk}`).join('\n');
    const shortPicks = (s.short_picks || []).map(p => `    SHORT ${p.ticker}: ${p.thesis} | Risk: ${p.key_risk} | Earnings: ${p.earnings_risk}`).join('\n');
    const convFlag   = s.effective_confidence < 0.75 ? ' ← BELOW TRADING THRESHOLD' : '';
    return [
      `### ${s.niche.toUpperCase()} | ${s.direction} | ${s.effective_conviction} | effective_conf: ${s.effective_confidence} (raw: ${s.confidence}, scaling: ${s.scaling_factor}x)${convFlag}`,
      `  Macro: ${s.macro_assessment}`,
      longPicks  ? `  Long picks:\n${longPicks}`   : '  No long picks.',
      shortPicks ? `  Short picks:\n${shortPicks}` : '  No short picks.',
      `  Summary: ${s.summary}`,
    ].join('\n');
  }).join('\n\n');
}

// ── HELPER: Format pattern performance ───────────────────────────────────────
function formatPatternPerf(patternPerfMap) {
  const patterns = ['TREND', 'BIAS', 'NOISE', 'REVERSAL', 'FIRST_SIGNAL'];
  return patterns.map(p => {
    const data = patternPerfMap[p] || {};
    if (!data.total_trades) return `  ${p.padEnd(14)}: No data yet`;
    const ev   = data.expected_value != null ? data.expected_value.toFixed(2) + '%' : 'N/A';
    const warn = (data.expected_value != null && data.expected_value < 0) ? ' ← NEGATIVE EV — DO NOT TRADE' : '';
    const note = (data.expected_value != null && data.expected_value < 1.0 && data.expected_value >= 0) ? ' ← LOW EV — apply noise penalty' : '';
    return `  ${p.padEnd(14)}: win ${data.win_rate != null ? (data.win_rate * 100).toFixed(0) + '%' : 'N/A'} | avg_win ${data.avg_win_pct != null ? data.avg_win_pct.toFixed(1) + '%' : 'N/A'} | avg_loss ${data.avg_loss_pct != null ? data.avg_loss_pct.toFixed(1) + '%' : 'N/A'} | EV ${ev} (${data.total_trades} trades)${warn}${note}`;
  }).join('\n');
}

// ── HELPER: Format trade lessons ─────────────────────────────────────────────
function formatTradeLessons(lessons) {
  if (!lessons || lessons.length === 0) return '  No lessons yet.';
  return lessons.map(l =>
    `  [${l.generated_at ? l.generated_at.substring(0, 10) : '?'}] ${l.ticker} (${l.niche}): "${l.key_lesson}" | Pattern: ${l.entry_pattern} | ${l.outcome} | Entry: ${l.entry_timing} | Exit: ${l.exit_timing}`
  ).join('\n');
}

// ── HELPER: Format watchlist ──────────────────────────────────────────────────
function formatWatchlist(watchlist) {
  if (!watchlist || watchlist.length === 0) return '  Watchlist is empty.';
  return watchlist.map(w =>
    `  ${w.ticker} (${w.niche} / ${w.direction}): ${w.reason} | Added: ${w.added_at ? w.added_at.substring(0, 10) : '?'}`
  ).join('\n');
}

// ── HELPER: Format rotation summary ──────────────────────────────────────────
function formatRotation(rotationSummary) {
  return rotationSummary.map(r =>
    `  ${r.niche.padEnd(20)}: ${r.momentum.padEnd(8)} | Pattern: ${r.pattern} | Current: ${r.current_direction || 'N/A'}`
  ).join('\n');
}

// ── BUILD SYSTEM PROMPT ───────────────────────────────────────────────────────
// The full orchestrator system prompt (from prompts/orchestrator_prompt.md)
// Keep in sync with the prompt file.
const ORCHESTRATOR_SYSTEM_PROMPT = `You are the Portfolio Manager of an AI-driven paper trading fund with $60,000 in capital, benchmarked against the S&P 500 over a 3-month period. Your objective is simple and non-negotiable: generate returns that exceed SPY's cumulative return from the start of the experiment.

You receive signals from 8 specialist analysts covering distinct sectors. Your job is to translate those signals into precise portfolio actions — which stocks to buy, which to short, which to hold, and which to close — while managing risk at the portfolio level.

## YOUR MANDATE
Beat the S&P 500. Not match it. Not protect capital at all costs. Generate alpha.
- Cash is a drag. Every dollar not deployed against a HIGH conviction signal is costing you relative performance.
- Conviction is the goal. Three great positions beat eight mediocre ones every time.
- You are a swing trader with a 2–6 week horizon per position.

## CONVICTION THRESHOLD
You act ONLY on HIGH conviction signals with effective_confidence ≥ 0.75.
MEDIUM and LOW signals inform your watchlist but do not trigger trades.

## POSITION SIZING
Long positions: effective_confidence ≥ 0.85 → $8,000 | 0.75–0.84 → $5,000 | <0.75 → no trade
Short positions: effective_confidence ≥ 0.85 → $6,000 | 0.75–0.84 → $3,000 | <0.75 → no trade
Max short exposure: $12,000 (20% of portfolio) | Max positions: 12 | Max per sector: 2

## SIZE PENALTIES (stack multiplicatively)
- Correlation penalty: new stock correlation >0.70 with open position → reduce one tier
- Earnings penalty: stock earnings ≤2 days → reduce one tier
- Noise penalty: sector signal history is NOISE (2-2-1 or worse) → reduce one tier
- First signal penalty: FIRST_SIGNAL pattern → treat as one tier below
- Two penalties → reduce two tiers. Three or more → do not trade.

## EXIT RULES
- Thesis stop (mandatory): specialist flips direction → exit immediately
- REVERSAL pattern (3+ consecutive sessions opposing): exit immediately even before flip
- Earnings exit (default): close positions with earnings ≤2 days before the event
- Profit-taking (discretionary): if position gained >20%, consider trimming half

## FEEDBACK SYSTEM
- effective_confidence is pre-calculated by the system. Use it — do not use raw confidence.
- Pattern EV: if pattern has negative expected value, do not open positions under that pattern
- Trade lessons: check the last 5 lessons before opening new positions — avoid documented mistakes
- Counterfactual: assess whether your stock selection choices have been optimal

## OUTPUT FORMAT
Respond ONLY with valid JSON. No markdown, no backticks, no preamble.

{
  "is_market_open": true | false,
  "portfolio_actions": [
    {
      "action": "BUY | SELL | SHORT | COVER",
      "ticker": "CRWD",
      "niche": "cybersecurity",
      "size_usd": 8000,
      "shares": 10.5,
      "conviction": "HIGH",
      "confidence": 0.87,
      "stop_loss_pct": 8.5,
      "target_horizon_days": 21,
      "thesis": "Specific and complete reasoning",
      "exit_reason": null | "thesis_flip | earnings_risk | profit_taking | target_reached",
      "signal_history_pattern": "TREND | BIAS | NOISE | REVERSAL | FIRST_SIGNAL",
      "size_adjustments_applied": [],
      "specialist_scaling_factor": 0.94,
      "effective_confidence": 0.82,
      "feedback_note": null
    }
  ],
  "portfolio_review": [
    {
      "ticker": "NVDA",
      "current_action": "HOLD | SELL | COVER",
      "thesis_intact": true | false,
      "earnings_risk": "NONE | MEDIUM | HIGH",
      "stop_proximity": "OK | WARNING | CRITICAL",
      "reasoning": "Specific reasoning"
    }
  ],
  "watchlist": [
    {"ticker": "AMD", "niche": "semiconductors", "direction": "long | short", "reason": "Why watching", "trigger": "Specific entry condition"}
  ],
  "cash_deployment_rationale": "Explicit explanation of cash usage or non-usage",
  "orchestrator_summary": "4-6 sentence summary of portfolio state, key decisions, and current positioning vs SPY"
}`;

// ── BUILD USER PROMPT ─────────────────────────────────────────────────────────
const account  = ctx.account;
const isOpen   = specialists.length > 0;  // market open status comes from orchestrator output

const userPrompt = `## SESSION: ${ctx.session_id} (${ctx.session_type.toUpperCase()})
SPY: $${ctx.spyCurrent || 'N/A'} | Portfolio: $${account.portfolio_value.toFixed(0)} | Cash: $${account.cash.toFixed(0)} | Buying Power: $${account.buying_power.toFixed(0)}
Cumulative Return — Portfolio: ${ctx.portfolioCumulativePct}% | SPY: ${ctx.spyCumulativePct}% | Alpha: ${(ctx.portfolioCumulativePct - ctx.spyCumulativePct).toFixed(2)}%

---

## 1. SPECIALIST SIGNALS (today)

${formatSpecialistSignals(specialists)}

---

## 2. OPEN POSITIONS

${formatPositions(ctx.positions, ctx.stopProximity, ctx.earningsAtRisk, ctx.priceMap)}

Long exposure: $${account.long_market_value.toFixed(0)} | Short exposure: $${Math.abs(account.short_market_value).toFixed(0)} | Net: $${(account.long_market_value + account.short_market_value).toFixed(0)}

---

## 3. HISTORICAL SIGNAL CONTEXT

### 3a. Signal History (last 5 sessions per sector)
${formatSignalHistory(ctx.signalsByNiche)}

### 3b. Sector Rotation Momentum
${formatRotation(ctx.rotationSummary)}

### 3c. Portfolio P&L Trend vs SPY (last 7 sessions)
${ctx.last7Snapshots.map(s => `  ${s.session}: Portfolio $${s.portfolio_value} | SPY $${s.spy_price}`).join('\n')}

### 3d. Trailing Stop Proximity
${ctx.stopProximity.length > 0
  ? ctx.stopProximity.map(s => `  ${s.ticker}: current $${s.current_price} | stop $${s.stop_price} | distance ${s.distance_pct}% [${s.risk}]`).join('\n')
  : '  No active trailing stops.'}

### 3e. Watchlist (last 3 sessions)
${formatWatchlist(ctx.watchlist)}

---

## 4. FEEDBACK SYSTEM

### 4a. Pattern Performance (historical EV)
${formatPatternPerf(ctx.patternPerfMap)}

### 4b. Recent Trade Lessons (last 5 closed trades)
${formatTradeLessons(ctx.recentTradeLessons)}

### 4c. Correlation Flags (candidates with >0.70 correlation to open positions)
${Object.keys(ctx.correlationFlags).length > 0
  ? Object.entries(ctx.correlationFlags).map(([t, c]) =>
      `  ${t}: correlated with ${c.map(x => `${x.open_position} (${x.correlation.toFixed(2)})`).join(', ')} — apply correlation penalty`
    ).join('\n')
  : '  No correlation flags.'}

---

## 5. EARNINGS AT-RISK (open positions)
${ctx.earningsAtRisk.length > 0
  ? ctx.earningsAtRisk.map(e => `  ${e.ticker}: ${e.risk_level} — earnings in ${e.days_until} days (${e.earnings_date})`).join('\n')
  : '  No earnings at-risk in open positions.'}

---

Now review every open position, assess new opportunities, and produce your portfolio decisions.`;

return [{
  json: {
    system_prompt: ORCHESTRATOR_SYSTEM_PROMPT,
    user_prompt:   userPrompt,
    session_id:    ctx.session_id,
    session_type:  ctx.session_type,
    // Pass through for post-trade processing
    specialists_summary: specialists.map(s => ({
      niche: s.niche,
      direction: s.direction,
      effective_conviction: s.effective_conviction,
      effective_confidence: s.effective_confidence,
      long_picks:  s.long_picks,
      short_picks: s.short_picks,
    })),
    portfolio_state: {
      positions:    ctx.positions,
      priceMap:     ctx.priceMap,
      account:      ctx.account,
      session_id:   ctx.session_id,
      spyCurrent:   ctx.spyCurrent,
      spyCumulativePct: ctx.spyCumulativePct,
    }
  }
}];

// Node: Parse Orchestrator Output
// Position: After Call Orchestrator LLM (native OpenAI node v2.1)
// Input: 1 item — output[0].content[0].text contains the JSON string
// Output: 1 item with all parsed orchestrator decisions + trade action items

const rawResponse   = $input.first().json;
const orchInput     = $("Build Orchestrator Input").first().json;

// ── PARSE OPENAI RESPONSE ─────────────────────────────────────────────────────
let parsed   = null;
let rawText  = '';

try {
  rawText = rawResponse.output?.[0]?.content?.[0]?.text;  // native OpenAI node v2.1 output
  const cleaned = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  // Fallback: empty decisions, nothing trades
  parsed = {
    is_market_open:          false,
    portfolio_actions:        [],
    portfolio_review:         [],
    watchlist:                [],
    cash_deployment_rationale: `Parse error: ${err.message}`,
    orchestrator_summary:     'Orchestrator output could not be parsed this session.',
  };
}

// ── ENRICH TRADE ACTIONS WITH ALPACA ORDER PAYLOADS ──────────────────────────
// Each action needs:
//   1. A market order payload  (for node 30)
//   2. A trailing stop payload (for node 32a, only for BUY and SHORT)

const state    = orchInput.portfolio_state;
const priceMap = state.priceMap;

const enrichedActions = (parsed.portfolio_actions || []).map(action => {
  const ticker    = action.ticker;
  const price     = priceMap[ticker] ? priceMap[ticker].current : null;
  const stopPct   = action.stop_loss_pct || (priceMap[ticker] ? priceMap[ticker].trail_pct : 8);

  // Always recalculate shares from actual current price — LLM often assumes a stale price
  // and its share count can be way off. Ignore action.shares entirely.
  let shares = null;
  if (price && action.size_usd) {
    shares = Math.floor(action.size_usd / price * 100) / 100;  // round down to 2 decimals
  } else if (action.shares) {
    shares = action.shares;  // last resort: use LLM value only when price is unavailable
  }

  // Market order payload for Alpaca
  let orderSide, orderEffect;
  if (action.action === 'BUY') {
    orderSide = 'buy'; orderEffect = null;
  } else if (action.action === 'SELL') {
    orderSide = 'sell'; orderEffect = null;
  } else if (action.action === 'SHORT') {
    orderSide = 'sell'; orderEffect = null;  // Alpaca auto-detects short when no position exists
  } else if (action.action === 'COVER') {
    orderSide = 'buy'; orderEffect = null;
  }

  const marketOrderPayload = {
    symbol:         ticker,
    qty:            shares ? shares.toString() : null,
    notional:       shares ? null : action.size_usd.toString(),  // use notional if shares not computed
    side:           orderSide,
    type:           'market',
    time_in_force:  'day',
    extended_hours: false,
  };
  // Clean nulls
  if (marketOrderPayload.qty)      delete marketOrderPayload.notional;
  if (!marketOrderPayload.qty)     delete marketOrderPayload.qty;
  if (!marketOrderPayload.notional) delete marketOrderPayload.notional;

  // Trailing stop payload (only for BUY / SHORT)
  const trailStopPayload = (action.action === 'BUY' || action.action === 'SHORT') ? {
    symbol:         ticker,
    qty:            shares ? shares.toString() : action.size_usd.toString(),
    side:           action.action === 'BUY' ? 'sell' : 'buy',  // opposite side
    type:           'trailing_stop',
    trail_percent:  stopPct.toString(),
    time_in_force:  'gtc',
  } : null;

  return {
    ...action,
    shares:               shares,
    estimated_price:      price,
    stop_pct_used:        stopPct,
    needs_trailing_stop:  action.action === 'BUY' || action.action === 'SHORT',
    order_payload:        marketOrderPayload,
    trail_stop_payload:   trailStopPayload,
  };
});

// ── SEPARATE SELL/COVER FOR POST-MORTEM ──────────────────────────────────────
const closedPositions = enrichedActions.filter(a => a.action === 'SELL' || a.action === 'COVER');
const openingActions  = enrichedActions.filter(a => a.action === 'BUY'  || a.action === 'SHORT');

// For each closed position, build the post-mortem webhook payload
const postMortemPayloads = closedPositions.map(action => {
  const ticker   = action.ticker;
  const position = (state.positions || []).find(p => p.symbol === ticker);

  return {
    ticker,
    niche:        action.niche,
    direction:    action.action === 'SELL' ? 'long' : 'short',
    action:       action.action,
    exit_reason:  action.exit_reason,
    exit_price:   priceMap[ticker] ? priceMap[ticker].current : null,
    entry_price:  position ? parseFloat(position.avg_entry_price) : null,
    entry_date:   null,  // would need to track this in Neon (add to positions tracking)
    exit_date:    orchInput.portfolio_state.session_id.split('_')[0],
    session_id:   orchInput.portfolio_state.session_id,
    // Include for post-mortem context:
    specialists_at_exit: orchInput.specialists_summary,
  };
});

// ── DERIVE MARKET OPEN FROM SESSION TYPE (not LLM judgment) ──────────────────
// The LLM doesn't reliably know what morning/midday/close map to in ET.
// Market is open for morning (8:30 AM ET) and midday (12 PM ET) sessions.
// Close (4:30 PM ET) is after regular hours — no new orders.
const isMarketOpen = orchInput.session_type === 'morning' || orchInput.session_type === 'midday';

// ── OUTPUT ────────────────────────────────────────────────────────────────────
return [{
  json: {
    // Core orchestrator decisions
    is_market_open:            isMarketOpen,
    portfolio_actions:         enrichedActions,
    portfolio_review:          parsed.portfolio_review         || [],
    watchlist:                 parsed.watchlist                 || [],
    cash_deployment_rationale: parsed.cash_deployment_rationale || '',
    orchestrator_summary:      parsed.orchestrator_summary      || '',

    // Derived
    closing_positions:  closedPositions,
    opening_positions:  openingActions,
    post_mortem_payloads: postMortemPayloads,

    // For Neon snapshot
    session_id:   orchInput.portfolio_state.session_id,
    session_type: orchInput.session_type,
    account:      orchInput.portfolio_state.account,
    spyCurrent:   orchInput.portfolio_state.spyCurrent,
    spyCumulativePct: orchInput.portfolio_state.spyCumulativePct,

    // Raw for debugging
    raw_orchestrator_response: (rawText || '').substring(0, 5000),
    usage_tokens: rawResponse.usage ? rawResponse.usage.total_tokens : null,
  }
}];

// Node: Process Post-Trade
// Position: After Merge (trade execution branches reconverge)
// Builds the portfolio snapshot payload for Neon and collects
// post-mortem webhook payloads for SELL/COVER actions.
// Output: 1 item with all data needed for the two final Neon writes.

const orch     = $("Parse Orchestrator Output").first().json;
const account  = orch.account || {};

// Compute long/short breakdown from executed positions
// At this point the trades have fired — we'd need to re-fetch the portfolio.
// For now, use the orchestrator's account snapshot (close enough for this session).
const longValue  = Math.abs(parseFloat(account.long_market_value  || 0));
const shortValue = Math.abs(parseFloat(account.short_market_value || 0));
const unrealPnl  = parseFloat(account.equity || 0) - parseFloat(account.portfolio_value || 0);

// Build positions JSON for snapshot (current state before trades fully settle)
const positionsJson = (orch.portfolio_review || []).map(p => ({
  ticker:          p.ticker,
  action:          p.current_action,
  thesis_intact:   p.thesis_intact,
  earnings_risk:   p.earnings_risk,
  stop_proximity:  p.stop_proximity,
}));

// Separate longs and shorts
const longReviews  = positionsJson.filter(p => p.current_action !== 'COVER');
const shortReviews = positionsJson.filter(p => p.current_action === 'COVER' ||
  (p.current_action === 'HOLD' && p.ticker)); // simplified — orchestrator knows

// Escape single quotes for SQL string interpolation ('' is PostgreSQL's escape for ')
const sqlEsc = s => (s || '').replace(/'/g, "''");

// Snapshot row for Neon
const snapshotPayload = {
  session:             orch.session_id,
  portfolio_value_usd: parseFloat(account.portfolio_value),
  cash_usd:            parseFloat(account.cash),
  long_value_usd:      longValue,
  short_value_usd:     shortValue,
  unrealized_pnl_usd:  unrealPnl,
  spy_price:           orch.spyCurrent || null,
  spy_return_pct:      null,  // session return — compute later if needed
  spy_cumulative_pct:  orch.spyCumulativePct || 0,
  orchestrator_summary: sqlEsc(orch.orchestrator_summary),
  positions_json:      sqlEsc(JSON.stringify(longReviews)),
  short_positions_json: sqlEsc(JSON.stringify(shortReviews)),
  raw_json:            sqlEsc(JSON.stringify({
    portfolio_actions:         orch.portfolio_actions,
    cash_deployment_rationale: orch.cash_deployment_rationale,
  })),
};

// New watchlist items (replace entire watchlist each session)
const newWatchlist = (orch.watchlist || []).map(w => ({
  ticker:    w.ticker,
  niche:     w.niche,
  direction: w.direction,
  reason:    w.reason || '',
}));

// Post-mortem payloads (one per SELL/COVER)
// These are sent as webhook calls to the post-mortem workflow.
const postMortemPayloads = (orch.post_mortem_payloads || []).map(pm => ({
  ...pm,
  orchestrator_summary: orch.orchestrator_summary,
}));

return [{
  json: {
    snapshot:              snapshotPayload,
    watchlist:             newWatchlist,
    post_mortem_payloads:  postMortemPayloads,
    has_post_mortems:      postMortemPayloads.length > 0,
    session_id:            orch.session_id,
  }
}];

const input = $("Process Post-Trade").first().json;
const wl = input.watchlist || [];
const esc = s => (s||'').replace(/'/g,"''");
let sql = "DELETE FROM stocks.watchlist;";
if (wl.length > 0) {
  const vals = wl.map(w=>`('${esc(w.ticker)}','${esc(w.niche)}','${esc(w.direction)}','${esc(w.reason||'').substring(0,500)}')`).join(',');
  sql += ` INSERT INTO stocks.watchlist (ticker,niche,direction,reason) VALUES ${vals};`;
}
return [{json:{watchlist_sql:sql}}];

const input = $("Process Post-Trade").first().json;
const payloads = input.post_mortem_payloads || [];
if (payloads.length === 0) return [];
return payloads.map(p => ({json: p}));

// Node: Prepare Trade Actions
// Position: After IF "Is Market Open?" (TRUE branch)
// Input: orchestrator output (1 item)
// Output: N items — one per portfolio_action that should execute
// Each item is passed through the HTTP Request node that submits the Alpaca order.

const orch = $input.first().json;

if (!orch.is_market_open) {
  // Safety check — should not reach here given the IF node, but guard anyway
  return [];
}

const actions = orch.portfolio_actions || [];

if (actions.length === 0) {
  // No trades this session — return a no-op item so downstream nodes don't stall
  return [{
    json: {
      no_trades:   true,
      session_id:  orch.session_id,
      reason:      orch.cash_deployment_rationale || 'No actionable signals this session.',
    }
  }];
}

// Output one item per action. Each item carries everything the Alpaca HTTP Request needs.
return actions.map(action => ({
  json: {
    // Trade identity
    action:          action.action,    // BUY | SELL | SHORT | COVER
    ticker:          action.ticker,
    niche:           action.niche,
    session_id:      orch.session_id,

    // Alpaca order payloads (pre-built in node 07)
    order_payload:       action.order_payload,       // JSON string for market order body
    trail_stop_payload:  action.trail_stop_payload,  // JSON string for trailing stop (null if not needed)
    needs_trailing_stop: action.needs_trailing_stop,

    // For post-trade logging
    size_usd:             action.size_usd,
    shares:               action.shares,
    estimated_price:      action.estimated_price,
    conviction:           action.conviction,
    effective_confidence: action.effective_confidence,
    stop_pct_used:        action.stop_pct_used,
    thesis:               action.thesis,
    exit_reason:          action.exit_reason || null,
    signal_history_pattern: action.signal_history_pattern,
    size_adjustments_applied: action.size_adjustments_applied || [],
    feedback_note:        action.feedback_note || null,
  }
}));

// Merge bars from all 9 niche fetches into one response
const allBars = {};
const sourceNodes = [
  'Fetch Bars Cybersecurity', 'Fetch Bars Defense', 'Fetch Bars Nuclear',
  'Fetch Bars Copper', 'Fetch Bars AI Semis', 'Fetch Bars Cloud',
  'Fetch Bars Oil Gas', 'Fetch Bars Data Centers', 'Fetch Bars SPY',
];
for (const nodeName of sourceNodes) {
  try {
    const resp = $(nodeName).first().json;
    if (resp && resp.bars) Object.assign(allBars, resp.bars);
  } catch (_) {}
}
return [{ json: { bars: allBars } }];

const NICHE         = 'cybersecurity';
const NICHE_DISPLAY = 'Cybersecurity';
const TICKERS       = ["CRWD", "PANW", "ZS", "OKTA", "FTNT", "S", "CYBR", "TMUS", "QLYS", "TENB"];

const ctx = $("Compute Derived Metrics").first().json;

function formatStockData(tickers, priceMap, fundamentalsMap, earningsRows) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  return tickers.map(ticker => {
    const p    = priceMap[ticker]        || {};
    const f    = fundamentalsMap[ticker] || {};
    const earn = earningsRows.find(e => e.ticker === ticker);
    let earningsTag = 'NONE';
    if (earn && earn.earnings_date) {
      const days = Math.round((new Date(earn.earnings_date) - today) / 86400000);
      if      (days >= 0 && days <= 3) earningsTag = 'HIGH ('  + days + 'd — ' + earn.earnings_date + ')';
      else if (days >= 4 && days <= 7) earningsTag = 'MEDIUM (' + days + 'd — ' + earn.earnings_date + ')';
    }
    const pctFrom52H = p.week_52_high
      ? ((p.current - p.week_52_high) / p.week_52_high * 100).toFixed(1) : 'N/A';
    const pctFrom52L = p.week_52_low
      ? ((p.current - p.week_52_low)  / p.week_52_low  * 100).toFixed(1) : 'N/A';
    const analystStr = (f.analyst_buy || f.analyst_hold || f.analyst_sell)
      ? (f.analyst_buy||0) + 'B / ' + (f.analyst_hold||0) + 'H / ' + (f.analyst_sell||0) + 'S'
      : 'N/A';
    const ptStr = f.price_target_avg
      ? '$' + f.price_target_avg + ' (H: $' + (f.price_target_high||'N/A') + ' / L: $' + (f.price_target_low||'N/A') + ')'
      : 'N/A';
    const revGrowth   = f.revenue_growth_yoy != null ? (f.revenue_growth_yoy * 100).toFixed(1) + '%' : 'N/A';
    const grossMargin = f.gross_margin       != null ? (f.gross_margin       * 100).toFixed(1) + '%' : 'N/A';
    const netMargin   = f.net_margin         != null ? (f.net_margin         * 100).toFixed(1) + '%' : 'N/A';
    return [
      ticker + ':',
      '  Price: $' + (p.current||'N/A') + ' | 1D: ' + (p.chg_1d_pct||0) + '% | 5D: ' + (p.chg_5d_pct||0) + '% | 30D: ' + (p.chg_30d_pct||0) + '%',
      '  52W Range: $' + (p.week_52_low||'N/A') + ' – $' + (p.week_52_high||'N/A') +
        ' (' + pctFrom52H + '% from high / +' + pctFrom52L + '% from low)',
      '  P/E: ' + (f.pe_ratio||'N/A') + ' | P/S: ' + (f.ps_ratio||'N/A') + ' | P/B: ' + (f.pb_ratio||'N/A'),
      '  Rev Growth YoY: ' + revGrowth + ' | Gross Margin: ' + grossMargin + ' | Net Margin: ' + netMargin,
      '  Beta: ' + (f.beta||'N/A') + ' | Analyst Consensus: ' + analystStr + ' | Price Target: ' + ptStr,
      '  Earnings Risk: ' + earningsTag,
    ].join('\n');
  }).join('\n\n');
}

function formatNews(allItems) {
  if (!allItems || allItems.length === 0) return 'No recent news retrieved.';
  return allItems.slice(0, 10).map((item, i) => {
    const a = item.json;
    const date    = (a.isoDate || a.pubDate || '').substring(0, 10);
    const datePart = date ? ' (' + date + ')' : '';
    const snippet  = (a.contentSnippet || a.content || '').substring(0, 400);
    return '[' + (i + 1) + '] ' + (a.title || '') + datePart + '\n' + snippet;
  }).join('\n\n');
}

function formatAccuracyHistory(niche, specialistEffectiveConf) {
  const acc = specialistEffectiveConf[niche];
  if (!acc || !acc.total_signals) {
    return 'No accuracy history yet. Treat your confidence calibration as unconstrained for now.';
  }
  const calLabel = acc.scaling_factor < 0.85
    ? 'YOU ARE OVERCONFIDENT — discount your stated confidence'
    : acc.scaling_factor > 1.15
      ? 'You have been underconfident — you may state slightly higher confidence'
      : 'Well-calibrated';
  const lines = [
    '30-Day Performance: ' + (acc.hit_rate * 100).toFixed(1) + '% directional accuracy across ' + acc.total_signals + ' signals',
    'Confidence Calibration: You stated avg ' + (acc.avg_reported_confidence * 100).toFixed(1) +
      '% confidence → scaling factor ' + acc.scaling_factor + 'x (' + calLabel + ')',
    'Best pattern: ' + (acc.best_pattern || 'N/A') + ' | Worst pattern: ' + (acc.worst_pattern || 'N/A'),
  ];
  if (acc.scaling_factor < 0.85) {
    lines.push('ACTION: If your raw conviction is 0.85, your effective confidence is ~' +
      (0.85 * acc.scaling_factor).toFixed(2) + '. Calibrate your stated confidence downward.');
  }
  return lines.join('\n');
}

const SPECIALIST_SYSTEM_PROMPT = `You are a specialist equity analyst covering the {NICHE_NAME} sector for an AI-driven investment fund. Your sole responsibility is to analyze your sector and produce actionable, high-conviction signals that will be used by a Portfolio Manager to allocate capital in a $60,000 paper trading portfolio benchmarked against the S&P 500.

