function formatNews(allItems) {
  if (!allItems || allItems.length === 0) return 'No recent news retrieved.';
  return allItems.slice(0, 10).map((item, i) => {
    const a = item.json;
    const date    = (a.isoDate || a.pubDate || '').substring(0, 10);
    const datePart = date ? ' (' + date + ')' : '';
    const snippet  = (a.contentSnippet || a.content || '').substring(0, 400);
    return '[' + (i + 1) + '] ' + (a.title || '') + datePart + '\n' + snippet;
  }).join('\n\n');
}

function formatAccuracyHistory(niche, specialistEffectiveConf) {
  const acc = specialistEffectiveConf[niche];
  if (!acc || !acc.total_signals) {
    return 'No accuracy history yet. Treat your confidence calibration as unconstrained for now.';
  }
  const calLabel = acc.scaling_factor < 0.85
    ? 'YOU ARE OVERCONFIDENT — discount your stated confidence'
    : acc.scaling_factor > 1.15
      ? 'You have been underconfident — you may state slightly higher confidence'
      : 'Well-calibrated';
  const lines = [
    '30-Day Performance: ' + (acc.hit_rate * 100).toFixed(1) + '% directional accuracy across ' + acc.total_signals + ' signals',
    'Confidence Calibration: You stated avg ' + (acc.avg_reported_confidence * 100).toFixed(1) +
      '% confidence → scaling factor ' + acc.scaling_factor + 'x (' + calLabel + ')',
    'Best pattern: ' + (acc.best_pattern || 'N/A') + ' | Worst pattern: ' + (acc.worst_pattern || 'N/A'),
  ];
  if (acc.scaling_factor < 0.85) {
    lines.push('ACTION: If your raw conviction is 0.85, your effective confidence is ~' +
      (0.85 * acc.scaling_factor).toFixed(2) + '. Calibrate your stated confidence downward.');
  }
  return lines.join('\n');
}

